using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class ModelTrainingService
{
    private readonly MLContext _mlContext;
    private readonly ILogger<ModelTrainingService> _logger;

    public ModelTrainingService(MLContext mlContext, ILogger<ModelTrainingService> logger)
    {
        _mlContext = mlContext;
        _logger = logger;
    }

    /// <summary>
    /// Trains a multiclass classifier from the CSV file, evaluates it, and saves the model to disk.
    /// Returns the evaluation metrics so the caller can log or expose them.
    /// </summary>
    public MulticlassClassificationMetrics TrainAndSave(string dataPath, string modelPath)
    {
        // 1. Load data
        IDataView data = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // 2. Train / test split (80/20)
        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2);

        // 3. Build the pipeline
        //    - Featurize the two text columns independently
        //    - Concatenate text features with the numeric Priority column
        //    - Train with SdcaMaximumEntropy (good default for multiclass)
        var pipeline = _mlContext.Transforms.Conversion
                .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText(
                "DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
                labelColumnName: "Label", featureColumnName: "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // 4. Train
        _logger.LogInformation("Training model from {DataPath}...", dataPath);
        ITransformer model = pipeline.Fit(split.TrainSet);

        // 5. Evaluate on held-out test set
        IDataView predictions = model.Transform(split.TestSet);
        var metrics = _mlContext.MulticlassClassification.Evaluate(
            predictions, labelColumnName: "Label");

        _logger.LogInformation(
            "Model evaluation — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
            metrics.MicroAccuracy, metrics.MacroAccuracy, metrics.LogLoss);

        // 6. Save
        _mlContext.Model.Save(model, data.Schema, modelPath);
        _logger.LogInformation("Model saved to {ModelPath}", modelPath);

        return metrics;
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public class TicketsController : ControllerBase
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _predictionPool;

    public TicketsController(PredictionEnginePool<TicketData, TicketPrediction> predictionPool)
    {
        _predictionPool = predictionPool;
    }

    /// <summary>POST /api/tickets/classify — predict the category for a support ticket.</summary>
    [HttpPost("classify")]
    public ActionResult<TicketResponse> Classify([FromBody] TicketRequest request)
    {
        if (string.IsNullOrWhiteSpace(request.Subject) && string.IsNullOrWhiteSpace(request.Description))
            return BadRequest("Subject or Description is required.");

        if (request.Priority < 1 || request.Priority > 3)
            return BadRequest("Priority must be between 1 and 3.");

        var input = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority,
        };

        var prediction = _predictionPool.Predict(input);

        // Map scores to category labels (alphabetical order from MapValueToKey)
        string[] labels = ["Billing", "General", "Technical"];
        var scores = new Dictionary<string, float>();
        for (int i = 0; i < labels.Length && i < prediction.Score.Length; i++)
            scores[labels[i]] = prediction.Score[i];

        return Ok(new TicketResponse
        {
            PredictedCategory = prediction.PredictedCategory,
            ConfidenceScores = scores,
        });
    }
}

[ApiController]
[Route("api/[controller]")]
public class ModelController : ControllerBase
{
    private readonly ModelTrainingService _trainingService;
    private readonly string _dataPath;
    private readonly string _modelPath;

    public ModelController(ModelTrainingService trainingService, IWebHostEnvironment env)
    {
        _trainingService = trainingService;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
    }

    /// <summary>POST /api/model/train — retrain the model and return evaluation metrics.</summary>
    [HttpPost("train")]
    public ActionResult Train()
    {
        var metrics = _trainingService.TrainAndSave(_dataPath, _modelPath);

        return Ok(new
        {
            metrics.MicroAccuracy,
            metrics.MacroAccuracy,
            metrics.LogLoss,
            metrics.LogLossReduction,
            PerClassLogLoss = metrics.PerClassLogLoss.ToArray(),
        });
    }
}

