using Microsoft.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// ML.NET context with fixed seed for reproducibility
var mlContext = new MLContext(seed: 42);
builder.Services.AddSingleton(mlContext);
builder.Services.AddSingleton<ModelTrainingService>();

// Train the model at startup so predictions are available immediately
var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

var tempLogger = LoggerFactory.Create(b => b.AddConsole())
    .CreateLogger<ModelTrainingService>();
var trainingService = new ModelTrainingService(mlContext, tempLogger);
trainingService.TrainAndSave(dataPath, modelPath);

// Thread-safe prediction engine pool (reloads when model.zip changes)
builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(modelPath, watchForChanges: true);

var app = builder.Build();
app.MapControllers();
app.Run();

