arguments.new_str:
    private string[] GetLabelNames()
    {
        var model = _mlContext.Model.Load(_modelPath, out var inputSchema);

        // Create a dummy prediction engine to inspect the output schema
        var engine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(model);
        var outputSchema = engine.OutputSchema;
        var scoreCol = outputSchema.GetColumnOrNull("Score");

        if (scoreCol == null)
            return ["Billing", "General", "Technical"];

        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        scoreCol.Value.GetSlotNames(ref slotNames);
        return slotNames.DenseValues().Select(v => v.ToString()).ToArray();
    }
}

